class ByteDataset(Dataset):
    def __init__(self, text_path="data/input.txt", block_size=64):
        text = STORY
        # Если есть файл - берем файл, если нет - берем встроенную сказку
        if os.path.exists(text_path):
            try:
                with open(text_path, 'r', encoding='utf-8') as f:
                    file_text = f.read()
                if len(file_text) > 100:
                    text = file_text
                    print(f"Loaded from {text_path}: {len(text)} chars")
            except:
                pass

        self.data = torch.tensor(list(text.encode("utf-8")), dtype=torch.long)
        if block_size < 1 or len(self.data) <= block_size:
            raise ValueError("Text must contain more UTF-8 bytes than block_size.")
        self.block_size = block_size
        print(f"Dataset: {len(self.data)} bytes")

    def __len__(self): 
        return len(self.data) - self.block_size

    def __getitem__(self, i):
        x = self.data[i:i+self.block_size]
        y = self.data[i+1:i+self.block_size+1]
        return x, y
